PLANBET_COPY.es.sports[0][1] = 'Son visibles fútbol, baloncesto, tenis, tenis de mesa, voleibol, hockey sobre hielo, críquet, béisbol y UFC. Sports y Live son secciones distintas; CS2 y Dota 2 aparecen en esports. La liquidación de apuestas y las retransmisiones tienen condiciones propias.';
